// context/AuthContext.js
import React, { createContext, useState, useContext, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);

  // Загрузка из localStorage при инициализации
  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    const savedCart = localStorage.getItem('cart');
    const savedFavorites = localStorage.getItem('favorites');
    const savedOrders = localStorage.getItem('orders');

    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    if (savedCart) {
      setCart(JSON.parse(savedCart));
    }
    if (savedFavorites) {
      setFavorites(JSON.parse(savedFavorites));
    }
    if (savedOrders) {
      setOrders(JSON.parse(savedOrders));
    }
  }, []);

  // ✅ Функция регистрации
  const register = (userData) => {
    // Проверяем, нет ли уже пользователя с таким email
    const existingUsers = JSON.parse(localStorage.getItem('registeredUsers') || '[]');
    const userExists = existingUsers.some(u => u.email === userData.email);

    if (userExists) {
      throw new Error('Пользователь с таким email уже существует');
    }

    // Создаем нового пользователя
    const newUser = {
      id: Date.now().toString(),
      username: userData.username,
      email: userData.email,
      createdAt: new Date().toISOString(),
      ...userData
    };

    // Сохраняем в список зарегистрированных пользователей
    const updatedUsers = [...existingUsers, newUser];
    localStorage.setItem('registeredUsers', JSON.stringify(updatedUsers));

    // Автоматически логиним пользователя после регистрации
    setUser(newUser);
    localStorage.setItem('user', JSON.stringify(newUser));

    return newUser;
  };

  // ✅ Функция входа
  const login = (email, password) => {
    // Получаем список зарегистрированных пользователей
    const registeredUsers = JSON.parse(localStorage.getItem('registeredUsers') || '[]');

    // Ищем пользователя по email (в реальном приложении нужно проверять и пароль)
    const foundUser = registeredUsers.find(u => u.email === email);

    if (!foundUser) {
      throw new Error('Пользователь с таким email не найден');
    }

    // В реальном приложении здесь должна быть проверка пароля
    // if (foundUser.password !== password) {
    //   throw new Error('Неверный пароль');
    // }

    setUser(foundUser);
    localStorage.setItem('user', JSON.stringify(foundUser));

    return foundUser;
  };

  // Функции для корзины
  const addToCart = (product) => {
    const existingItem = cart.find(item => item.id === product.id);
    let newCart;

    if (existingItem) {
      newCart = cart.map(item =>
        item.id === product.id
          ? { ...item, quantity: (item.quantity || 1) + 1 }
          : item
      );
    } else {
      newCart = [...cart, { ...product, quantity: 1 }];
    }

    setCart(newCart);
    localStorage.setItem('cart', JSON.stringify(newCart));
  };

  const removeFromCart = (productId) => {
    const newCart = cart.filter(item => item.id !== productId);
    setCart(newCart);
    localStorage.setItem('cart', JSON.stringify(newCart));
  };

  // Функции для избранного
  const addToFavorites = (product) => {
    const isAlreadyFavorite = favorites.some(item => item.id === product.id);

    if (!isAlreadyFavorite) {
      const newFavorites = [...favorites, product];
      setFavorites(newFavorites);
      localStorage.setItem('favorites', JSON.stringify(newFavorites));
      return true;
    }
    return false;
  };

  const removeFromFavorites = (productId) => {
    const newFavorites = favorites.filter(item => item.id !== productId);
    setFavorites(newFavorites);
    localStorage.setItem('favorites', JSON.stringify(newFavorites));
  };

  const isInFavorites = (productId) => {
    return favorites.some(item => item.id === productId);
  };

  // Функции для заказов
  const createOrder = (orderData) => {
    const newOrder = {
      id: Date.now().toString(),
      date: new Date().toLocaleString('ru-RU'),
      items: [...cart],
      total: cart.reduce((sum, item) => sum + (item.price * (item.quantity || 1)), 0),
      status: 'pending',
      address: orderData.address,
      cardNumber: orderData.cardNumber,
      ...orderData
    };

    const newOrders = [newOrder, ...orders];
    setOrders(newOrders);
    localStorage.setItem('orders', JSON.stringify(newOrders));

    // Очищаем корзину после создания заказа
    setCart([]);
    localStorage.setItem('cart', JSON.stringify([]));

    return newOrder;
  };

  const cancelOrder = (orderId) => {
    const newOrders = orders.map(order =>
      order.id === orderId
        ? { ...order, status: 'cancelled' }
        : order
    );
    setOrders(newOrders);
    localStorage.setItem('orders', JSON.stringify(newOrders));
  };

  const logout = () => {
    setUser(null);
    setCart([]);
    setFavorites([]);
    setOrders([]);
    localStorage.removeItem('user');
    localStorage.removeItem('cart');
    localStorage.removeItem('favorites');
    localStorage.removeItem('orders');
  };

  const value = {
    user,
    cart,
    favorites,
    orders,
    register, // ✅ Добавляем функцию регистрации
    login,    // ✅ Добавляем функцию входа
    logout,
    addToCart,
    removeFromCart,
    addToFavorites,
    removeFromFavorites,
    isInFavorites,
    createOrder,
    cancelOrder
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
